def solve_sequence(N):
    a = {1: 0}
    for n in range(2, N + 1):
        max_val = -1
        for i in range(1, n):
            # a_i + a_{n - i} + min(i, n - i)
            term = a[i] + a[n - i] + min(i, n - i)
            if term > max_val:
                max_val = term
        a[n] = max_val
    return a

N_max = 12
a_values = solve_sequence(N_max)

print("n:", list(a_values.keys()))
print("a_n:", list(a_values.values()))

# Check differences
diffs = {}
for n in range(2, N_max + 1):
    diffs[n] = a_values[n] - a_values[n-1]

print("\nDifferences (a_n - a_{n-1}):")
print(diffs)

def calculate_a(n):
    if n == 1:
        return 0

    a = [0] * (n + 1)
    a[1] = 0

    for k in range(2, n + 1):
        max_val = -float('inf')
        for i in range(1, k):
            # Original definition:
            val = a[i] + a[k - i] + min(i, k - i)
            if val > max_val:
                max_val = val
        a[k] = max_val
    return a[n]

# Test small values against Candidate C: a_n = (n-1)(n+5)/8
def candidate_C(n):
    return (n - 1) * (n + 5) / 8

print("--- Checking small values ---")
for n in range(1, 7):
    actual = calculate_a(n)
    candidate = candidate_C(n)
    print(f"n={n}: Actual a_{n} = {actual}, Candidate C = {candidate}")

